UPDATE artifacts AS a SET metadata_json=json_set(a.metadata_json,
  '$.publication_state','superseded',
  '$.retirement_operation','riyadh-unrebuilt-210-20260904',
  '$.retirement_reason','User requested empty companion slots for a fresh rebuild')
WHERE json_extract(a.metadata_json,'$.publication_state')='ready'
  AND EXISTS (SELECT 1 FROM targets t
    WHERE a.id IN (t.html_id,t.pdf_id)
      AND json_extract(a.metadata_json,'$.recommendation_id')=t.source_id
      AND json_extract(a.metadata_json,'$.pair_id')=t.pair_id
      AND COALESCE(json_extract(a.metadata_json,'$.chapter_key'),'')=''
      AND NOT EXISTS (SELECT 1 FROM lite_visual_pairs p WHERE p.pair_id=t.pair_id AND p.corpus_id IS NOT NULL));

UPDATE lite_visual_pairs AS p SET state='superseded'
WHERE p.corpus_id IS NULL AND p.state='active'
  AND 2=(SELECT COUNT(*) FROM artifacts a
    WHERE a.id IN (p.html_artifact_id,p.pdf_artifact_id)
      AND json_extract(a.metadata_json,'$.pair_id')=p.pair_id
      AND json_extract(a.metadata_json,'$.publication_state')='superseded'
      AND json_extract(a.metadata_json,'$.retirement_operation')='riyadh-unrebuilt-210-20260904');
